SELECT audregistry, thdpct, spksensedb, audlatms, 
  ROUND(CAST((1 - thdpct/2.0) * (spksensedb::numeric/100.0) * (1 - audlatms/100.0) * 10 AS numeric), 2) as aqi
FROM audioandmedia LIMIT 10;

SELECT MIN(aqi), MAX(aqi) FROM (
  SELECT ROUND(CAST((1 - thdpct/2.0) * (spksensedb::numeric/100.0) * (1 - audlatms/100.0) * 10 AS numeric), 2) as aqi
  FROM audioandmedia
) sub;

